async function handleCharacterImport(file) {
    if (!file) return;
    showToast('正在解析角色卡...');
    try {
        let result;
        const lowerName = (file.name || '').toLowerCase();
        if (lowerName.endsWith('.zip') || file.type === 'application/zip' || file.type === 'application/x-zip-compressed') {
            result = await parseCharZip(file);
        } else if (lowerName.endsWith('.png')) {
            result = await parseCharPng(file);
        } else if (lowerName.endsWith('.json')) {
            result = await parseCharJson(file);
        } else {
            throw new Error('不支持的文件格式。请选择 .zip、.png 或 .json 文件。');
        }

        if (result) {
            showImportConfirmModal(result.data, result.avatar, result.packageExtras || null);
        }
    } catch (error) {
        console.error('角色卡导入失败:', error);
        showToast(`导入失败: ${error.message}`);
    }
}

async function parseCharZip(file) {
    if (typeof fflate === 'undefined' || typeof fflate.unzipSync !== 'function') {
        throw new Error('ZIP 解压组件未就绪，无法解析压缩包。');
    }
    const buffer = await file.arrayBuffer();
    const files = fflate.unzipSync(new Uint8Array(buffer));
    const names = Object.keys(files).filter(name => !name.endsWith('/') && !name.startsWith('__MACOSX/'));
    if (!names.length) {
        throw new Error('ZIP 压缩包为空。');
    }

    const decodeText = bytes => new TextDecoder('utf-8').decode(bytes);
    const bytesToDataUrl = (bytes, mime) => new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result);
        reader.onerror = () => reject(new Error('读取压缩包图片失败。'));
        reader.readAsDataURL(new Blob([bytes], { type: mime }));
    });

    let charData = null;
    let avatar = '';
    let attachedWorldBooks = null;
    let uwuProfile = null;
    let photos = [];
    let stickers = [];

    const jsonNames = names.filter(name => name.toLowerCase().endsWith('.json'));

    const wbFileName = jsonNames.find(name => /(^|\/)worldbooks\.json$/i.test(name));
    if (wbFileName) {
        try {
            const parsedWb = JSON.parse(decodeText(files[wbFileName]));
            if (parsedWb && Array.isArray(parsedWb.entries)) {
                attachedWorldBooks = {
                    worldBookIds: Array.isArray(parsedWb.worldBookIds) ? parsedWb.worldBookIds : [],
                    journalWorldBookIds: Array.isArray(parsedWb.journalWorldBookIds) ? parsedWb.journalWorldBookIds : [],
                    entries: parsedWb.entries
                };
            }
        } catch (err) {
            throw new Error(`解析世界书数据失败: ${err.message}`);
        }
    }

    const profileFileName = jsonNames.find(name => /(^|\/)uwu_character\.json$/i.test(name));
    if (profileFileName) {
        try {
            const parsedProfile = JSON.parse(decodeText(files[profileFileName]));
            if (parsedProfile && typeof parsedProfile === 'object') {
                uwuProfile = parsedProfile;
            }
        } catch (err) {
            throw new Error(`解析角色完整档案失败: ${err.message}`);
        }
    }

    const photosFileName = jsonNames.find(name => /(^|\/)photos\.json$/i.test(name));
    if (photosFileName) {
        try {
            const parsedPhotos = JSON.parse(decodeText(files[photosFileName]));
            if (Array.isArray(parsedPhotos)) photos = parsedPhotos;
        } catch {
            // 忽略损坏的相片数据，不影响主流程
        }
    }

    const stickersFileName = jsonNames.find(name => /(^|\/)stickers\.json$/i.test(name));
    if (stickersFileName) {
        try {
            const parsedStickers = JSON.parse(decodeText(files[stickersFileName]));
            if (Array.isArray(parsedStickers)) stickers = parsedStickers;
        } catch {
            // 忽略损坏的表情包数据，不影响主流程
        }
    }

    // 查找角色卡 JSON（优先 character.json / *-角色卡.json，排除内部配套文件）
    const candidateJsons = jsonNames.filter(name => !/(^|\/)(manifest|worldbooks|uwu_character|photos|stickers)\.json$/i.test(name));
    candidateJsons.sort((a, b) => {
        const score = n => (/(^|\/)character\.json$/i.test(n) ? 0 : (/角色卡\.json$/i.test(n) ? 1 : 2));
        return score(a) - score(b);
    });

    const extraWorldBookEntries = [];
    for (const name of candidateJsons) {
        let parsed;
        try {
            parsed = JSON.parse(decodeText(files[name]));
        } catch {
            continue;
        }
        const maybeCard = parsed?.data?.name ? parsed : (parsed?.name && (parsed?.description !== undefined || parsed?.persona !== undefined || parsed?.spec) ? parsed : null);
        if (!charData && maybeCard) {
            charData = parsed;
            continue;
        }
        // 兼容额外附带的独立世界书 JSON（UwU 数组格式或 SillyTavern entries 对象格式）
        if (!attachedWorldBooks) {
            if (Array.isArray(parsed)) {
                extraWorldBookEntries.push(...parsed);
            } else if (parsed && parsed.entries && typeof parsed.entries === 'object') {
                const list = Array.isArray(parsed.entries) ? parsed.entries : Object.values(parsed.entries);
                for (const entry of list) {
                    if (entry && typeof entry.content === 'string') {
                        const settings = worldBookContext.cardSettings({
                            keys: entry.key || entry.keys || [],
                            enabled: entry.disable !== true && entry.enabled !== false,
                            constant: Boolean(entry.constant),
                            position: entry.position === 0 || entry.position === 'before_char' ? 'before_char' : 'after_char',
                            extensions: entry.extensions
                        });
                        extraWorldBookEntries.push({
                            type: 'entry',
                            name: String(entry.comment || entry.name || settings.triggerKeys[0] || '世界书条目'),
                            content: entry.content,
                            ...settings,
                            depth: Number.isFinite(Number(entry.order ?? entry.insertion_order ?? entry.depth)) ? Number(entry.order ?? entry.insertion_order ?? entry.depth) : 100
                        });
                    }
                }
            }
        }
    }

    if (!attachedWorldBooks && extraWorldBookEntries.length) {
        attachedWorldBooks = {
            worldBookIds: [],
            journalWorldBookIds: [],
            entries: extraWorldBookEntries
        };
    }

    // 若压缩包内没有 JSON 角色卡，尝试解析其中的 PNG 角色卡
    const pngNames = names.filter(name => name.toLowerCase().endsWith('.png'));
    if (!charData && pngNames.length) {
        for (const pngName of pngNames) {
            try {
                const pngFile = new File([files[pngName]], pngName.split('/').pop(), { type: 'image/png' });
                const parsedPng = await parseCharPng(pngFile);
                if (parsedPng?.data) {
                    charData = parsedPng.data;
                    avatar = parsedPng.avatar || '';
                    break;
                }
            } catch {
                // 非角色卡 PNG，继续检查下一个
            }
        }
    }

    if (!charData && uwuProfile) {
        charData = {
            spec: 'chara_card_v2',
            spec_version: '2.0',
            data: {
                name: uwuProfile.realName || uwuProfile.remarkName || 'UwU 角色',
                description: uwuProfile.persona || '',
                character_book: { entries: [] },
                extensions: {}
            }
        };
    }

    if (!charData) {
        throw new Error('ZIP 压缩包中未找到有效的角色卡数据。');
    }

    if (!avatar) {
        avatar = uwuProfile?.avatar || '';
    }
    if (!avatar) {
        const avatarName = names.find(name => /(^|\/)avatar\.(png|jpe?g|webp|gif)$/i.test(name))
            || names.find(name => /\.(png|jpe?g|webp|gif)$/i.test(name));
        if (avatarName) {
            const ext = avatarName.split('.').pop().toLowerCase();
            const mime = ext === 'jpg' || ext === 'jpeg' ? 'image/jpeg' : `image/${ext}`;
            avatar = await bytesToDataUrl(files[avatarName], mime);
        }
    }

    return {
        data: charData,
        avatar,
        packageExtras: { attachedWorldBooks, uwuProfile, photos, stickers }
    };
}

function parseCharPng(file) {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsArrayBuffer(file);
        reader.onload = (e) => {
            try {
                const buffer = e.target.result;
                const view = new DataView(buffer);
                const signature = [137, 80, 78, 71, 13, 10, 26, 10];
                for (let i = 0; i < signature.length; i++) {
                    if (view.getUint8(i) !== signature[i]) {
                        return reject(new Error('文件不是一个有效的PNG。'));
                    }
                }

                let offset = 8;
                let charaData = null;

                while (offset < view.byteLength) {
                    const length = view.getUint32(offset);
                    const type = String.fromCharCode(view.getUint8(offset + 4), view.getUint8(offset + 5), view.getUint8(offset + 6), view.getUint8(offset + 7));
                    
                    if (type === 'tEXt') {
                        const textChunk = new Uint8Array(buffer, offset + 8, length);
                        let separatorIndex = -1;
                        for(let i = 0; i < textChunk.length; i++) {
                            if (textChunk[i] === 0) {
                                separatorIndex = i;
                                break;
                            }
                        }

                        if (separatorIndex !== -1) {
                            const keyword = new TextDecoder('utf-8').decode(textChunk.slice(0, separatorIndex));
                            if (keyword === 'chara') {
                                const base64Data = new TextDecoder('utf-8').decode(textChunk.slice(separatorIndex + 1));
                                try {
                                    const decodedString = atob(base64Data);
                                    const bytes = new Uint8Array(decodedString.length);
                                    for (let i = 0; i < decodedString.length; i++) {
                                        bytes[i] = decodedString.charCodeAt(i);
                                    }
                                    const utf8Decoder = new TextDecoder('utf-8');
                                    charaData = JSON.parse(utf8Decoder.decode(bytes));
                                    break;
                                } catch (decodeError) {
                                    return reject(new Error(`解析角色数据失败: ${decodeError.message}`));
                                }
                            }
                        }
                    }
                    offset += 12 + length;
                }

                if (charaData) {
                    const imageReader = new FileReader();
                    imageReader.readAsDataURL(file);
                    imageReader.onload = (imgEvent) => {
                        resolve({ data: charaData, avatar: imgEvent.target.result });
                    };
                    imageReader.onerror = () => {
                        resolve({ data: charaData, avatar: 'data:image/jpeg;base64,' });
                    };
                } else {
                    reject(new Error('在PNG中未找到有效的角色数据 (tEXt chunk not found or invalid)。'));
                }
            } catch (error) {
                reject(new Error(`解析PNG失败: ${error.message}`));
            }
        };
        reader.onerror = () => reject(new Error('读取PNG文件失败。'));
    });
}

function parseCharJson(file) {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsText(file, 'UTF-8');
        reader.onload = (e) => {
            try {
                const data = JSON.parse(e.target.result);
                resolve({ data: data, avatar: 'data:image/jpeg;base64,' });
            } catch (error) {
                reject(new Error(`解析JSON失败: ${error.message}`));
            }
        };
        reader.onerror = () => reject(new Error('读取JSON文件失败。'));
    });
}

function characterCardAvatar(value) {
    if (typeof value !== 'string' || /[\s"'<>]/.test(value)) return '';
    if (/^data:image\/(?:png|jpe?g|gif|webp);base64,[a-z0-9+/=]+$/i.test(value)) return value;
    return /^https?:\/\//i.test(value) ? value : '';
}

async function exportCharacterCard(character, includeMemory) {
    const bound = new Set(character.worldBookIds || []);
    const entries = db.worldBooks.filter(book => bound.has(book.id) && book.type !== 'folder').map(book => {
        const activation = worldBookContext.mode(book);
        return {
            comment: book.name, content: book.content, keys: worldBookContext.keys(book.triggerKeys),
            enabled: activation !== 'off', constant: activation === 'always',
            insertion_order: book.depth || 100,
            position: book.position === 'before' ? 'before_char' : 'after_char',
            extensions: { uwu_worldbook: { activation, position: book.position || 'before' } }
        };
    });
    const extensions = {};
    const avatar = characterCardAvatar(character.avatar);
    if (avatar) extensions.uwu_avatar = avatar;
    const region = walletProfiles.profile(character);
    extensions.uwu_region = { nationality: region.nation, residence: region.region };
    if (includeMemory) {
        const backup = await memoryRepository.exportBackup(character.id);
        const scoped = new Set(backup.entries.map(entry => entry.archiveId).filter(Boolean));
        const archives = (character.archives || []).filter(archive => scoped.has(archive.id) || archive.id === character.activeArchiveId)
            .map(({ id, name }) => ({ id, name }));
        extensions.uwu_memory = { backup, archives, activeArchiveId: character.activeArchiveId,
            enabled: character.memorySettings?.enabled === true,
            organizeStylePrompt: memoryBatch.cleanStylePrompt(character.memorySettings?.organizeStylePrompt) };
    }
    return { spec: 'chara_card_v2', spec_version: '2.0', data: {
        name: character.realName || character.remarkName || 'UwU 角色', description: character.persona || '',
        personality: '', scenario: '', first_mes: '', mes_example: '', creator_notes: '', system_prompt: '',
        post_history_instructions: '', alternate_greetings: [], tags: [], creator: '', character_version: '',
        character_book: { entries }, extensions
    } };
}

function collectCharacterWorldBooks(character) {
    const worldBookIds = new Set(Array.isArray(character?.worldBookIds) ? character.worldBookIds : []);
    const journalWorldBookIds = new Set(Array.isArray(character?.journalWorldBookIds) ? character.journalWorldBookIds : []);

    // 同时收集所有存档中绑定的世界书
    if (Array.isArray(character?.archives)) {
        for (const archive of character.archives) {
            if (Array.isArray(archive?.data?.worldBookIds)) {
                archive.data.worldBookIds.forEach(id => worldBookIds.add(id));
            }
            if (Array.isArray(archive?.data?.journalWorldBookIds)) {
                archive.data.journalWorldBookIds.forEach(id => journalWorldBookIds.add(id));
            }
        }
    }

    const byId = new Map((db.worldBooks || []).map(book => [book.id, book]));
    const collectedIds = new Set();

    const addWithAncestors = id => {
        let current = byId.get(id);
        const guard = new Set();
        while (current && !guard.has(current.id)) {
            guard.add(current.id);
            collectedIds.add(current.id);
            current = current.parentId ? byId.get(current.parentId) : null;
        }
    };

    worldBookIds.forEach(addWithAncestors);
    journalWorldBookIds.forEach(addWithAncestors);

    const entries = (db.worldBooks || [])
        .filter(book => collectedIds.has(book.id))
        .sort((a, b) => (a.type === 'folder' ? 0 : 1) - (b.type === 'folder' ? 0 : 1))
        .map(book => ({ ...book }));

    return {
        format: 'uwu-character-worldbooks',
        version: 1,
        worldBookIds: Array.isArray(character?.worldBookIds) ? [...new Set(character.worldBookIds)] : [],
        journalWorldBookIds: Array.isArray(character?.journalWorldBookIds) ? [...new Set(character.journalWorldBookIds)] : [],
        entries
    };
}

async function collectCharacterPackageData(character) {
    if (typeof syncChatActiveArchive === 'function') {
        syncChatActiveArchive(character, false);
    }
    const uwuProfile = typeof structuredClone === 'function'
        ? structuredClone(character)
        : JSON.parse(JSON.stringify(character));

    const worldbooks = collectCharacterWorldBooks(character);

    let photos = [];
    if (dexieDB && dexieDB.characterPhotos) {
        const rawPhotos = await dexieDB.characterPhotos.where('charId').equals(character.id).toArray();
        photos = rawPhotos.map(({ timestamp, image, prompt }) => ({ timestamp, image, prompt: prompt || '' }));
    }

    const stickerGroupSet = new Set(
        (character.stickerGroups || '').split(/[,，]/).map(s => s.trim()).filter(s => s && s !== '未分类')
    );
    const stickers = stickerGroupSet.size
        ? (db.myStickers || []).filter(s => s && stickerGroupSet.has(s.group)).map(s => ({ ...s }))
        : [];

    return { uwuProfile, worldbooks, photos, stickers };
}

function showCharacterCardExport(character) {
    const { element, button, download } = memoryZipUi;
    const dialog = element('dialog', undefined, { className: 'uwu-memory-dialog' });
    const label = element('label', '同时导出长期记忆、暗号及图片');
    const include = element('input', undefined, { type: 'checkbox', checked: true });
    label.prepend(include);

    const wbBundle = collectCharacterWorldBooks(character);
    const wbEntryCount = wbBundle.entries.filter(item => item.type !== 'folder').length;
    const msgCount = Array.isArray(character.history) ? character.history.length : 0;
    const journalCount = Array.isArray(character.memoryJournals) ? character.memoryJournals.length : 0;
    const archiveCount = Array.isArray(character.archives) ? character.archives.length : 1;

    const tip = element('p', `将把角色卡连同聊天记录 (${msgCount})、日记 (${journalCount})、存档 (${archiveCount})、世界书 (${wbEntryCount})、相片、表情包与长期记忆一并打包为 ZIP 压缩包。`);
    const status = element('p');
    status.setAttribute('role', 'status');

    const save = button('下载角色完整压缩包 (.zip)', async () => {
        save.disabled = true;
        try {
            const card = await exportCharacterCard(character, include.checked);
            const pkg = await collectCharacterPackageData(character);
            const name = card.data.name.replace(/[\\/:*?"<>|]/g, '_');
            const manifest = {
                format: 'uwu-character-package',
                version: 2,
                characterName: card.data.name,
                exportedAt: new Date().toISOString(),
                files: {
                    character: 'character.json',
                    profile: 'uwu_character.json',
                    worldbooks: 'worldbooks.json',
                    photos: 'photos.json',
                    stickers: 'stickers.json'
                },
                stats: {
                    historyCount: Array.isArray(pkg.uwuProfile.history) ? pkg.uwuProfile.history.length : 0,
                    callHistoryCount: Array.isArray(pkg.uwuProfile.callHistory) ? pkg.uwuProfile.callHistory.length : 0,
                    journalCount: Array.isArray(pkg.uwuProfile.memoryJournals) ? pkg.uwuProfile.memoryJournals.length : 0,
                    archiveCount: Array.isArray(pkg.uwuProfile.archives) ? pkg.uwuProfile.archives.length : 0,
                    worldBookCount: pkg.worldbooks.entries.filter(item => item.type !== 'folder').length,
                    photoCount: pkg.photos.length,
                    stickerCount: pkg.stickers.length,
                    includesMemory: Boolean(include.checked)
                }
            };
            if (typeof fflate !== 'undefined' && typeof fflate.zipSync === 'function') {
                const zipData = fflate.zipSync({
                    'manifest.json': fflate.strToU8(JSON.stringify(manifest, null, 2)),
                    'character.json': fflate.strToU8(JSON.stringify(card, null, 2)),
                    'uwu_character.json': fflate.strToU8(JSON.stringify(pkg.uwuProfile, null, 2)),
                    'worldbooks.json': fflate.strToU8(JSON.stringify(pkg.worldbooks, null, 2)),
                    'photos.json': fflate.strToU8(JSON.stringify(pkg.photos, null, 2)),
                    'stickers.json': fflate.strToU8(JSON.stringify(pkg.stickers, null, 2))
                }, { level: 6 });
                download(new Blob([zipData], { type: 'application/zip' }), `${name}-角色卡.zip`);
            } else {
                download(new Blob([JSON.stringify(card)], { type: 'application/json' }), `${name}-角色卡.json`);
            }
            dialog.close();
        } catch (error) {
            status.textContent = error.message;
        } finally {
            save.disabled = false;
        }
    });
    dialog.append(element('h2', '导出角色卡'), tip, label,
        element('p', '勾选后，拥有该文件的人可以读取随卡保存的长期记忆、暗号及图片。'), save, status, button('取消', () => dialog.close()));
    dialog.addEventListener('close', () => dialog.remove(), { once: true });
    document.body.append(dialog);
    dialog.showModal();
}

async function createCharacterFromData(data, avatar, { includeMemory = true, packageExtras = null } = {}) {
    const charData = data.data || data;

    if (!charData || !charData.name) {
        throw new Error('角色卡数据无效，缺少角色名称。');
    }

    const attachedWorldBooks = packageExtras?.attachedWorldBooks || null;
    const uwuProfile = packageExtras?.uwuProfile || null;
    const importedPhotos = Array.isArray(packageExtras?.photos) ? packageExtras.photos : [];
    const importedStickers = Array.isArray(packageExtras?.stickers) ? packageExtras.stickers : [];

    const defaultAvatar = 'data:image/jpeg;base64,';

    const clonedProfile = uwuProfile
        ? (typeof structuredClone === 'function' ? structuredClone(uwuProfile) : JSON.parse(JSON.stringify(uwuProfile)))
        : null;

    const newChar = clonedProfile ? {
        ...clonedProfile,
        id: `char_${crypto.randomUUID()}`,
        realName: charData.name || clonedProfile.realName || '未命名',
        remarkName: clonedProfile.remarkName || charData.name || '未命名',
        avatar: characterCardAvatar(charData.extensions?.uwu_avatar) || avatar || clonedProfile.avatar || defaultAvatar,
        unreadCount: 0
    } : {
        peekData: {},
        id: `char_${crypto.randomUUID()}`,
        nationality: charData.extensions?.uwu_region ? walletProfiles.place(charData.extensions.uwu_region.nationality) : undefined,
        residence: charData.extensions?.uwu_region ? walletProfiles.place(charData.extensions.uwu_region.residence) : undefined,
        realName: charData.name || '未命名',
        remarkName: charData.name || '未命名',
        persona: charData.description || charData.persona || '',
        avatar: characterCardAvatar(charData.extensions?.uwu_avatar) || avatar || defaultAvatar,
        myName: 'user',
        myRemarkName: '',
        myPersona: '',
        myAvatar: defaultAvatar,
        theme: 'white_pink',
        maxMemory: 100,
        chatBg: '',
        history: [],
        isPinned: false,
        status: '在线',
        worldBookIds: [],
        useCustomBubbleCss: false,
        customBubbleCss: '',
        bilingualBubbleStyle: 'under',
        unreadCount: 0,
        memoryJournals: [],
        journalWorldBookIds: [],
        peekScreenSettings: { wallpaper: '', customIcons: {}, unlockAvatar: '' },
        lastUserMessageTimestamp: null,
        statusPanel: {
            enabled: false,
            promptSuffix: '',
            regexPattern: '',
            replacePattern: '',
            historyLimit: 3,
            currentStatusRaw: '',
            currentStatusHtml: '',
            history: []
        },
        autoReply: {
            enabled: false,
            interval: 60,
            lastTriggerTime: 0
        }
    };

    const metadata = includeMemory ? charData.extensions?.uwu_memory : null;
    const archiveIds = new Map();
    const archiveNames = new Map();
    let records;
    if (metadata !== undefined && metadata !== null) {
        if (!metadata.backup || !Array.isArray(metadata.archives) || metadata.archives.length > 1000) {
            throw new Error('角色卡中的长期记忆信息无效');
        }
        for (const item of metadata.archives) {
            if (typeof item?.id !== 'string' || !item.id || typeof item.name !== 'string'
                || !item.name || archiveNames.has(item.id)) throw new Error('角色卡中的记忆存档无效');
            archiveNames.set(item.id, item.name);
            archiveIds.set(item.id, createArchiveId());
        }
        if (Array.isArray(newChar.archives)) {
            for (const arch of newChar.archives) {
                if (arch?.id && !archiveIds.has(arch.id)) {
                    archiveIds.set(arch.id, createArchiveId());
                }
            }
        }
        records = await memoryRepository.prepareCardBackup(newChar.id, metadata.backup, archiveIds);
        newChar.memorySettings = { enabled: metadata.enabled === true,
            organizeStylePrompt: memoryBatch.cleanStylePrompt(metadata.organizeStylePrompt) };
    }
    const bookCount = db.worldBooks.length;
    const importedWorldBookIds = [];
    const importedJournalWorldBookIds = [];
    const wbIdMap = new Map();

    if (attachedWorldBooks && Array.isArray(attachedWorldBooks.entries) && attachedWorldBooks.entries.length > 0) {
        const folders = attachedWorldBooks.entries.filter(item => item && item.type === 'folder');
        const entries = attachedWorldBooks.entries.filter(item => item && item.type !== 'folder' && typeof item.content === 'string');

        const pendingFolders = [...folders];
        let guard = pendingFolders.length * 2 + 5;
        while (pendingFolders.length && guard-- > 0) {
            const folder = pendingFolders.shift();
            const mappedParentId = folder.parentId ? (wbIdMap.has(folder.parentId) ? wbIdMap.get(folder.parentId) : null) : null;
            if (folder.parentId && !wbIdMap.has(folder.parentId) && folders.some(f => f.id === folder.parentId)) {
                pendingFolders.push(folder);
                continue;
            }
            const existingFolder = db.worldBooks.find(item => item.type === 'folder' && item.name === folder.name && (item.parentId || null) === (mappedParentId || null));
            if (existingFolder) {
                wbIdMap.set(folder.id, existingFolder.id);
            } else {
                const newFolderId = `wb_f_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`;
                db.worldBooks.push({
                    id: newFolderId,
                    parentId: mappedParentId,
                    type: 'folder',
                    name: folder.name || (data.name || charData.name || '导入世界书')
                });
                wbIdMap.set(folder.id, newFolderId);
            }
        }

        let defaultFolderId = null;
        const getDefaultFolderId = () => {
            if (defaultFolderId) return defaultFolderId;
            const categoryName = data.name || charData.name || '导入世界书';
            let folder = db.worldBooks.find(item => item.type === 'folder' && item.name === categoryName && !item.parentId);
            if (!folder) {
                defaultFolderId = `wb_f_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`;
                db.worldBooks.push({ id: defaultFolderId, parentId: null, type: 'folder', name: categoryName });
            } else {
                defaultFolderId = folder.id;
            }
            return defaultFolderId;
        };

        entries.forEach((entry, index) => {
            const name = String(entry.name || `条目 ${index + 1}`);
            const content = entry.content;
            const activation = worldBookContext.mode(entry);
            const triggerKeys = worldBookContext.keys(entry.triggerKeys);
            const position = entry.position || 'before';
            const depth = Number.isFinite(Number(entry.depth)) ? Number(entry.depth) : 100;
            const parentId = entry.parentId ? (wbIdMap.get(entry.parentId) || getDefaultFolderId()) : getDefaultFolderId();

            const sameBehavior = wb => wb.type !== 'folder'
                && wb.position === position
                && worldBookContext.mode(wb) === activation
                && JSON.stringify(worldBookContext.keys(wb.triggerKeys)) === JSON.stringify(triggerKeys);

            const exactMatch = db.worldBooks.find(wb => wb.name.toLowerCase() === name.toLowerCase() && wb.content === content && sameBehavior(wb));
            if (exactMatch) {
                if (entry.id) wbIdMap.set(entry.id, exactMatch.id);
                if (!attachedWorldBooks.worldBookIds?.length && !importedWorldBookIds.includes(exactMatch.id)) {
                    importedWorldBookIds.push(exactMatch.id);
                }
            } else {
                let newName = name;
                const categoryName = data.name || charData.name || '导入';
                if (db.worldBooks.some(wb => wb.type !== 'folder' && wb.name.toLowerCase() === newName.toLowerCase())) {
                    newName = `${name} (${categoryName})`;
                    if (db.worldBooks.some(wb => wb.type !== 'folder' && wb.name.toLowerCase() === newName.toLowerCase())) {
                        newName = `${newName}_${Math.random().toString(36).substr(2, 4)}`;
                    }
                }
                const newBookId = `wb_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`;
                db.worldBooks.push({
                    id: newBookId,
                    parentId,
                    type: 'entry',
                    name: newName,
                    content,
                    position,
                    category: entry.category || categoryName,
                    depth,
                    activation,
                    triggerKeys
                });
                if (entry.id) wbIdMap.set(entry.id, newBookId);
                if (!attachedWorldBooks.worldBookIds?.length) {
                    importedWorldBookIds.push(newBookId);
                }
            }
        });

        for (const oldId of (attachedWorldBooks.worldBookIds || [])) {
            const mapped = wbIdMap.get(oldId);
            if (mapped && !importedWorldBookIds.includes(mapped)) importedWorldBookIds.push(mapped);
        }
        for (const oldId of (attachedWorldBooks.journalWorldBookIds || [])) {
            const mapped = wbIdMap.get(oldId);
            if (mapped && !importedJournalWorldBookIds.includes(mapped)) importedJournalWorldBookIds.push(mapped);
        }
    } else if (charData.character_book && Array.isArray(charData.character_book.entries)) {
        const categoryName = data.name || charData.name;
        
        let folderId = null;
        let folder = db.worldBooks.find(item => item.type === 'folder' && item.name === categoryName && !item.parentId);
        if (folder) {
            folderId = folder.id;
        } else {
            folderId = `wb_f_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`;
            db.worldBooks.push({
                id: folderId,
                parentId: null,
                type: 'folder',
                name: categoryName
            });
        }

        charData.character_book.entries.forEach((entry, index) => {
            if (!entry || typeof entry.content !== 'string') return;
            const settings = worldBookContext.cardSettings(entry);
            const name = String(entry.comment || entry.name || settings.triggerKeys[0] || `条目 ${index + 1}`);
            const content = entry.content;
            const sameBehavior = wb => wb.position === settings.position && worldBookContext.mode(wb) === settings.activation
                && JSON.stringify(worldBookContext.keys(wb.triggerKeys)) === JSON.stringify(settings.triggerKeys);
            if (name && content) {
                // 策略：内容相同则复用，内容不同则重命名导入
                const exactMatch = db.worldBooks.find(wb => wb.name.toLowerCase() === name.toLowerCase() && wb.content === content && sameBehavior(wb));
                if (exactMatch) {
                    if (!importedWorldBookIds.includes(exactMatch.id)) importedWorldBookIds.push(exactMatch.id);
                } else {
                    // 检查是否已经导入过重命名版本
                    const renamedName = `${name} (${categoryName})`;
                    const renamedMatch = db.worldBooks.find(wb => wb.name.toLowerCase() === renamedName.toLowerCase() && wb.content === content && sameBehavior(wb));
                    
                    if (renamedMatch) {
                        if (!importedWorldBookIds.includes(renamedMatch.id)) importedWorldBookIds.push(renamedMatch.id);
                    } else {
                        // 需要新建
                        let newBookName = name;
                        const nameConflict = db.worldBooks.find(wb => wb.name.toLowerCase() === name.toLowerCase());
                        if (nameConflict) {
                            newBookName = renamedName;
                            // 二次冲突检查
                            if (db.worldBooks.some(wb => wb.name.toLowerCase() === newBookName.toLowerCase())) {
                                newBookName = `${newBookName}_${Math.random().toString(36).substr(2, 4)}`;
                            }
                        }
                        
                        let entryDepth = 100;
                        if (entry.insertion_order !== undefined) {
                            entryDepth = parseInt(entry.insertion_order);
                        } else if (entry.depth !== undefined) {
                            entryDepth = parseInt(entry.depth);
                        } else if (entry.extensions && entry.extensions.depth !== undefined) {
                            entryDepth = parseInt(entry.extensions.depth);
                        }

                        const newBook = {
                            id: `wb_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`,
                            parentId: folderId,
                            type: 'entry',
                            name: newBookName,
                            content: content,
                            ...settings,
                            category: categoryName,
                            depth: isNaN(entryDepth) ? 100 : entryDepth
                        };
                        db.worldBooks.push(newBook);
                        importedWorldBookIds.push(newBook.id);
                    }
                }
            }
        });
    }
    else {
        const worldInfo = charData.world_info || charData.wi || '';
        if (worldInfo && typeof worldInfo === 'string' && worldInfo.trim() !== '') {
            const entries = worldInfo.split(/\n\s*\n/).filter(entry => entry.trim() !== '');
            
            if (entries.length > 0) {
                const categoryName = charData.name || '导入的角色设定';
                
                let folderId = null;
                let folder = db.worldBooks.find(item => item.type === 'folder' && item.name === categoryName && !item.parentId);
                if (folder) {
                    folderId = folder.id;
                } else {
                    folderId = `wb_f_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`;
                    db.worldBooks.push({
                        id: folderId,
                        parentId: null,
                        type: 'folder',
                        name: categoryName
                    });
                }

                entries.forEach(entryText => {
                    const lines = entryText.trim().split('\n');
                    if (lines.length > 0) {
                        const name = lines[0].trim();
                        const content = lines.slice(1).join('\n').trim();
                        if (name && content) {
                        // 策略：内容相同则复用，内容不同则重命名导入
                        const exactMatch = db.worldBooks.find(wb => wb.name.toLowerCase() === name.toLowerCase() && wb.content === content);
                        if (exactMatch) {
                            if (!importedWorldBookIds.includes(exactMatch.id)) importedWorldBookIds.push(exactMatch.id);
                        } else {
                            // 检查是否已经导入过重命名版本
                            const renamedName = `${name} (${charData.name || '未命名'})`;
                            const renamedMatch = db.worldBooks.find(wb => wb.name.toLowerCase() === renamedName.toLowerCase() && wb.content === content);
                            
                            if (renamedMatch) {
                                if (!importedWorldBookIds.includes(renamedMatch.id)) importedWorldBookIds.push(renamedMatch.id);
                            } else {
                                // 需要新建
                                let newBookName = name;
                                const nameConflict = db.worldBooks.find(wb => wb.name.toLowerCase() === name.toLowerCase());
                                if (nameConflict) {
                                    newBookName = renamedName;
                                    // 二次冲突检查
                                    if (db.worldBooks.some(wb => wb.name.toLowerCase() === newBookName.toLowerCase())) {
                                        newBookName = `${newBookName}_${Math.random().toString(36).substr(2, 4)}`;
                                    }
                                }
                                
                                const newBook = {
                                    id: `wb_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`,
                                    parentId: folderId,
                                    type: 'entry',
                                    name: newBookName,
                                    content: content,
                                    position: 'after',
                                    category: categoryName
                                };
                                db.worldBooks.push(newBook);
                                importedWorldBookIds.push(newBook.id);
                            }
                        }
                    }
                }
                });
            }
        }
    }
    
    newChar.worldBookIds = importedWorldBookIds;
    newChar.journalWorldBookIds = importedJournalWorldBookIds;

    // 还原完整存档列表并重映射每个存档内的世界书 ID 与存档 ID
    if (Array.isArray(newChar.archives) && newChar.archives.length > 0) {
        const remapWbList = list => Array.isArray(list)
            ? [...new Set(list.map(id => wbIdMap.get(id)).filter(Boolean))]
            : [];
        newChar.archives = newChar.archives.map(archive => {
            const newArchiveId = archiveIds.get(archive.id) || createArchiveId();
            if (archive.id && !archiveIds.has(archive.id)) archiveIds.set(archive.id, newArchiveId);
            const dataCopy = archive.data ? { ...archive.data } : captureArchiveData(newChar);
            dataCopy.worldBookIds = remapWbList(dataCopy.worldBookIds);
            dataCopy.journalWorldBookIds = remapWbList(dataCopy.journalWorldBookIds);
            return {
                ...archive,
                id: newArchiveId,
                data: dataCopy
            };
        });
        if (newChar.activeArchiveId && archiveIds.has(newChar.activeArchiveId)) {
            newChar.activeArchiveId = archiveIds.get(newChar.activeArchiveId);
        } else {
            newChar.activeArchiveId = newChar.archives[0].id;
        }
    } else if (archiveIds.size) {
        const now = Date.now();
        newChar.archives = [...archiveIds].map(([oldId, id]) => ({
            id, name: archiveNames.get(oldId), createdAt: now, updatedAt: now, origin: null,
            data: captureArchiveData(newChar)
        }));
        newChar.activeArchiveId = archiveIds.get(metadata.activeArchiveId) ?? newChar.archives[0].id;
    }

    // 合并随包导出的表情包（按分组+名称+URL去重）
    const addedStickers = [];
    if (importedStickers.length > 0) {
        const existingKeys = new Set((db.myStickers || []).map(s => `${s.group}::${s.name}::${s.url}`));
        for (const s of importedStickers) {
            if (!s || !s.url || !s.group) continue;
            const key = `${s.group}::${s.name || ''}::${s.url}`;
            if (!existingKeys.has(key)) {
                existingKeys.add(key);
                const stickerItem = {
                    ...s,
                    id: `stk_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`
                };
                db.myStickers.push(stickerItem);
                addedStickers.push(stickerItem);
            }
        }
    }

    const addedBooks = new Set(db.worldBooks.slice(bookCount));
    const addedStickerSet = new Set(addedStickers);
    db.characters.push(newChar);
    try {
        await dexieDB.transaction('rw', dexieDB.tables, async () => {
            await saveData();
            if (records) await memoryRepository.importAllBackups(new Map([[newChar.id, records]]));
            if (importedPhotos.length > 0 && dexieDB.characterPhotos) {
                const photoRecords = importedPhotos
                    .filter(p => p && p.image)
                    .map(p => ({
                        charId: newChar.id,
                        timestamp: Number(p.timestamp) || Date.now(),
                        image: p.image,
                        prompt: p.prompt || ''
                    }));
                if (photoRecords.length > 0) {
                    await dexieDB.characterPhotos.bulkAdd(photoRecords);
                }
            }
        });
    } catch (error) {
        db.characters = db.characters.filter(character => character !== newChar);
        db.worldBooks = db.worldBooks.filter(book => !addedBooks.has(book));
        if (addedStickerSet.size > 0) {
            db.myStickers = db.myStickers.filter(s => !addedStickerSet.has(s));
        }
        throw error;
    }
    renderChatList();
    showToast(`角色“${newChar.remarkName}”导入成功！`);
}

function setupImportConfirmModal() {
    const modal = document.getElementById('import-confirm-modal');
    const form = document.getElementById('import-confirm-form');
    const cancelBtn = document.getElementById('cancel-import-btn');
    const nameInput = document.getElementById('import-char-name');
    const includeMemory = document.getElementById('import-char-memory');

    if (!modal || !form) return;

    form.addEventListener('submit', async (e) => {
        e.preventDefault();
        const submit = form.querySelector('[type="submit"]');
        if (!pendingImportData || submit.disabled) return;

        const newName = nameInput.value.trim();
        if (!newName) return showToast('请输入角色真名');

        // 更新名字
        if (pendingImportData.data.data) {
            // 适配 V2 格式 (data.data.name)
            pendingImportData.data.data.name = newName;
        } else {
            // 适配 V1 格式 (data.name)
            pendingImportData.data.name = newName;
        }

        submit.disabled = true;
        cancelBtn.disabled = true;
        try {
            await createCharacterFromData(pendingImportData.data, pendingImportData.avatar,
                { includeMemory: includeMemory.checked, packageExtras: pendingImportData.packageExtras || null });
            modal.classList.remove('visible');
            pendingImportData = null;
        } catch (error) {
            console.error(error);
            showToast('创建角色失败: ' + error.message);
        } finally {
            submit.disabled = false;
            cancelBtn.disabled = false;
        }
    });

    cancelBtn.addEventListener('click', () => {
        modal.classList.remove('visible');
        pendingImportData = null;
    });
}

function showImportConfirmModal(data, avatar, packageExtras = null) {
    const modal = document.getElementById('import-confirm-modal');
    const nameInput = document.getElementById('import-char-name');
    const includeMemory = document.getElementById('import-char-memory');
    const wbInfo = document.getElementById('import-char-wb-info');
    
    if (!modal) return;

    pendingImportData = { data, avatar, packageExtras };
    includeMemory.checked = Boolean((data.data || data).extensions?.uwu_memory);
    includeMemory.closest('label').hidden = !includeMemory.checked;
    if (wbInfo) {
        const attachedWorldBooks = packageExtras?.attachedWorldBooks;
        const uwuProfile = packageExtras?.uwuProfile;
        const photos = packageExtras?.photos || [];
        const stickers = packageExtras?.stickers || [];
        const pkgWbCount = attachedWorldBooks?.entries?.filter(item => item && item.type !== 'folder').length || 0;
        const cardWbCount = Array.isArray((data.data || data)?.character_book?.entries) ? (data.data || data).character_book.entries.length : 0;
        const wbCount = pkgWbCount || cardWbCount;

        const parts = [];
        if (uwuProfile) {
            const msgCount = Array.isArray(uwuProfile.history) ? uwuProfile.history.length : 0;
            const journalCount = Array.isArray(uwuProfile.memoryJournals) ? uwuProfile.memoryJournals.length : 0;
            const archiveCount = Array.isArray(uwuProfile.archives) ? uwuProfile.archives.length : 0;
            if (msgCount) parts.push(`${msgCount} 条聊天记录`);
            if (journalCount) parts.push(`${journalCount} 篇日记`);
            if (archiveCount) parts.push(`${archiveCount} 个存档`);
        }
        if (wbCount) parts.push(`${wbCount} 条世界书`);
        if (photos.length) parts.push(`${photos.length} 张相片`);
        if (stickers.length) parts.push(`${stickers.length} 个表情`);

        if (parts.length > 0) {
            wbInfo.textContent = `已检测到完整角色内容：${parts.join('、')}，确认后将全部导入并还原绑定。`;
            wbInfo.style.display = 'block';
        } else {
            wbInfo.style.display = 'none';
        }
    }
    
    // 获取原始名字
    let originalName = '';
    if (data.data && data.data.name) {
        originalName = data.data.name;
    } else if (data.name) {
        originalName = data.name;
    }

    nameInput.value = originalName;
    modal.classList.add('visible');
}
